const { Plugin, ItemView, Modal, Notice, Setting, PluginSettingTab, FuzzySuggestModal, addIcon } = require("obsidian");

const VIEW_TYPE = "ftm-editor-view";

const RIBBON_ICON = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">
<rect x="9" y="2" width="6" height="4" rx="0.5"/>
<line x1="12" y1="6" x2="12" y2="9"/>
<path d="M12 9 C 9.2 9, 7 10.6, 7 15 Q 12 13.2, 17 15 C 17 10.6, 14.8 9, 12 9 Z"/>
<line x1="9.5" y1="14.8" x2="9.5" y2="18"/>
<line x1="14.5" y1="14.8" x2="14.5" y2="18"/>
<circle cx="9.5" cy="19.7" r="1.7"/>
<circle cx="14.5" cy="19.7" r="1.7"/>
</svg>`;

/* ============ 编辑器视图 ============ */
class FTMView extends ItemView {
  constructor(leaf, plugin) {
    super(leaf);
    this.plugin = plugin;
    this.frame = null;
  }

  getViewType() { return VIEW_TYPE; }
  getDisplayText() { return "Fault Tree 编辑器"; }
  getIcon() { return "fta-icon"; }

  async onOpen() {
    const c = this.contentEl;
    c.empty();
    c.addClass("fta-view");
    const html = await this.plugin.getEditorHtml();
    const frame = document.createElement("iframe");
    frame.addClass("fta-frame");
    frame.setAttribute("sandbox", "allow-scripts allow-modals");
    frame.setAttribute("title", "Fault Tree Editor");
    frame.srcdoc = html;
    c.appendChild(frame);
    this.frame = frame;

    this.msgHandler = (ev) => {
      if (ev.source !== this.frame.contentWindow) return;
      this.plugin.handleMessage(ev.data || {}, this);
    };
    window.addEventListener("message", this.msgHandler);
  }

  postToFrame(msg) {
    if (this.frame && this.frame.contentWindow) this.frame.contentWindow.postMessage(msg, "*");
  }

  async onClose() {
    window.removeEventListener("message", this.msgHandler);
    this.contentEl.empty();
  }
}

/* ============ 对话框 ============ */
class FTMSaveAsModal extends Modal {
  constructor(app, suggested, onSubmit) {
    super(app);
    this.suggested = suggested;
    this.onSubmit = onSubmit;
  }
  onOpen() {
    const { contentEl } = this;
    contentEl.addClass("fta-saveas-modal");
    contentEl.createEl("h3", { text: "保存故障树项目" });
    contentEl.createEl("p", { text: "文件将保存到笔记库中设置的文件夹，可插入到任意笔记。", cls: "setting-item-description" });
    const input = contentEl.createEl("input", { type: "text", value: this.suggested, cls: "fta-name-input" });
    const btn = contentEl.createEl("button", { text: "保存", cls: "mod-cta" });
    const submit = () => {
      let name = (input.value || "").trim();
      if (!name) { new Notice("文件名不能为空"); return; }
      name = name.replace(/[\\/:*?"<>|]/g, "-");
      if (!/\.fta\.json$/i.test(name)) name += ".fta.json";
      this.close();
      this.onSubmit(name);
    };
    btn.addEventListener("click", submit);
    input.addEventListener("keydown", (e) => { if (e.key === "Enter") submit(); });
    setTimeout(() => { input.focus(); input.select(); }, 50);
  }
  onClose() { this.contentEl.empty(); }
}

class FTMOpenModal extends FuzzySuggestModal {
  constructor(app, plugin, view) {
    super(app);
    this.plugin = plugin;
    this.view = view;
    this.setPlaceholder("选择要打开的故障树项目（.fta.json）");
  }
  getItems() { return this.plugin.findProjects(); }
  getItemText(f) { return f.path; }
  onChooseItem(f) { this.plugin.openProject(f, this.view); }
}

/* ============ 设置页 ============ */
class FTMSettingTab extends PluginSettingTab {
  constructor(app, plugin) { super(app, plugin); this.plugin = plugin; }
  display() {
    const { containerEl } = this;
    containerEl.empty();
    containerEl.createEl("h2", { text: "Fault Tree Mini 设置" });
    new Setting(containerEl)
      .setName("保存文件夹")
      .setDesc(".fta.json 项目文件与导出图片存放的库内文件夹（不存在会自动创建），例如：附件/故障树")
      .addText((t) => t
        .setPlaceholder("/")
        .setValue(this.plugin.settings.folder)
        .onChange(async (v) => {
          this.plugin.settings.folder = v.trim() || "/";
          await this.plugin.saveData(this.plugin.settings);
        }));
  }
}

/* ============ 插件主体 ============ */
class FaultTreeMiniPlugin extends Plugin {
  async onload() {
    this.settings = Object.assign({ folder: "/" }, await this.loadData());
    this.editorHtmlCache = null;

    this.registerView(VIEW_TYPE, (leaf) => new FTMView(leaf, this));
    this.addSettingTab(new FTMSettingTab(this.app, this));
    addIcon("fta-icon", RIBBON_ICON);
    this.addRibbonIcon("fta-icon", "Fault Tree 编辑器", () => this.activateView());
    this.addCommand({ id: "open-editor", name: "打开故障树编辑器", callback: () => this.activateView() });
    this.addCommand({ id: "open-editor-new", name: "在新标签页打开故障树编辑器", callback: () => this.activateView(true) });
  }

  onunload() { }

  async activateView(forceNew) {
    const { workspace } = this.app;
    const existing = workspace.getLeavesOfType(VIEW_TYPE)[0];
    if (existing && !forceNew) { await workspace.revealLeaf(existing); return; }
    const leaf = workspace.getLeaf(forceNew ? "tab" : false);
    await leaf.setViewState({ type: VIEW_TYPE, active: true });
    await workspace.revealLeaf(leaf);
  }

  async getEditorHtml() {
    if (this.editorHtmlCache) return this.editorHtmlCache;
    // 构建版（社区市场安装）：编辑器内嵌在 main.js 里，无需外部文件
    if (typeof EMBEDDED_EDITOR_HTML === "string" && EMBEDDED_EDITOR_HTML) {
      this.editorHtmlCache = EMBEDDED_EDITOR_HTML;
      return this.editorHtmlCache;
    }
    // 源码版（手动拷贝安装）：从插件文件夹读取 editor.html
    try {
      this.editorHtmlCache = await this.app.vault.adapter.read(this.manifest.dir + "/editor.html");
    } catch (e) {
      new Notice("Fault Tree Mini：找不到 editor.html，请确认插件文件夹完整（缺 " + this.manifest.dir + "/editor.html）");
      throw e;
    }
    return this.editorHtmlCache;
  }

  findProjects() {
    return this.app.vault.getFiles().filter((f) => f.path.toLowerCase().endsWith(".fta.json"));
  }

  async ensureFolder() {
    const dir = (this.settings.folder || "/").replace(/^\/+|\/+$/g, "");
    if (dir && !(await this.app.vault.adapter.exists(dir))) {
      await this.app.vault.adapter.mkdir(dir);
    }
    return dir;
  }

  async vaultPathFor(name) {
    const dir = await this.ensureFolder();
    return dir ? dir + "/" + name : name;
  }

  async saveToVault(name, content) {
    const p = await this.vaultPathFor(name);
    await this.app.vault.adapter.write(p, content);
    return p;
  }

  async openProject(file, view) {
    const content = await this.app.vault.read(file);
    view.postToFrame({ type: "fta:load", name: file.name, content });
    new Notice("已打开 " + file.path);
  }

  /* ===== 消息总线 ===== */
  async handleMessage(msg, view) {
    try {
      switch (msg.type) {
        case "fta:save": {
          const p = await this.saveToVault(msg.name, msg.content);
          new Notice("已保存 " + p);
          view.postToFrame({ type: "fta:save-done", name: msg.name });
          break;
        }
        case "fta:save-as-dialog": {
          new FTMSaveAsModal(this.app, msg.suggested, async (name) => {
            const p = await this.saveToVault(name, msg.content);
            new Notice("已保存 " + p);
            view.postToFrame({ type: "fta:save-done", name });
          }).open();
          break;
        }
        case "fta:open-dialog": {
          const files = this.findProjects();
          if (!files.length) { new Notice("笔记库中没有 .fta.json 项目文件，先用「另存为」保存一个"); break; }
          new FTMOpenModal(this.app, this, view).open();
          break;
        }
        case "fta:export-svg": {
          const p = await this.vaultPathFor(msg.name + ".svg");
          await this.app.vault.adapter.write(p, msg.content);
          new Notice("已导出 " + p);
          break;
        }
        case "fta:export-png": {
          const p = await this.vaultPathFor(msg.name + ".png");
          const b64 = msg.dataUrl.split(",")[1] || "";
          const bin = Uint8Array.from(atob(b64), (ch) => ch.charCodeAt(0));
          await this.app.vault.adapter.writeBinary(p, bin.buffer);
          new Notice("已导出 " + p);
          break;
        }
        default:
          break;
      }
    } catch (e) {
      console.error("Fault Tree Mini:", e);
      new Notice("Fault Tree Mini 操作失败：" + e.message);
    }
  }
}

module.exports = FaultTreeMiniPlugin;
